class Solution {
    private int best = Integer.MIN_VALUE;

    public int maxPathSum(TreeNode root) {
        gain(root);
        return best;
    }

    private int gain(TreeNode node) {
        if (node == null) return 0;
        int l = Math.max(0, gain(node.left));    // drop arms that hurt
        int r = Math.max(0, gain(node.right));
        best = Math.max(best, node.val + l + r); // path bending through node
        return node.val + Math.max(l, r);        // extendable arm for the parent
    }
}
